def transform(grid):
    n = len(grid) // 3
    m = len(grid[0]) // 3
    out = [[0 for _ in range(m)] for _ in range(n)]
    for br in range(n):
        for bc in range(m):
            counts = {}
            for r in range(br * 3, br * 3 + 3):
                for c in range(bc * 3, bc * 3 + 3):
                    v = grid[r][c]
                    if v not in (0, 5):
                        counts[v] = counts.get(v, 0) + 1
            if counts:
                out[br][bc] = max(counts, key=counts.get)
    return out
